    if (caption.length < 60 || caption.length > 1500) issues.push("độ dài bất thường (" + caption.length + " ký tự)");
  }
  if (issues.length) {
    caption = (bai.loai === "menu" ? `🍰 Menu hôm nay (${bai.ngay}) của Mitu đây cả nhà ơi!` : `✨ ${bai.tieu_de}`) + "\n\n"
